//! Candidate-only adapter from generic WeightPrograms to unified HDC-LTC neurons.
//!
//! The adapter binds a proposal to an exact config, typed parameter manifest,
//! and parameter-value digest. It applies changes only to a cloned neuron,
//! then resets candidate state and momentum because they were generated by the
//! pre-edit dynamics. The source neuron is never mutated.

use serde::Serialize;
use thiserror::Error;

use crate::hdc::hdc_ltc_unified::{
    HdcLtcParameterEditError, HdcLtcParameterGroupId, HdcLtcUnifiedNeuron,
};
use crate::weight_space_program::{
    ParameterGroupConstraints, ParameterGroupRole, ParameterGroupSnapshot, WeightModelSnapshot,
    WeightProgram, WeightProgramError, WeightProgramReceipt, WeightProgramTarget,
};

const HDC_GROUPS: [(HdcLtcParameterGroupId, &str); 5] = [
    (HdcLtcParameterGroupId::WeightHypervector, "weight_hv"),
    (HdcLtcParameterGroupId::InputMask, "input_mask"),
    (HdcLtcParameterGroupId::TauModulator, "tau_modulator"),
    (HdcLtcParameterGroupId::GateWeight, "gate_weight"),
    (HdcLtcParameterGroupId::GateBias, "gate_bias"),
];

#[derive(Debug, Clone, Serialize)]
struct HdcLtcManifestEntry {
    id: HdcLtcParameterGroupId,
    name: &'static str,
    dimension: usize,
}

/// Detached candidate containing the edited neuron and both generic and native
/// model fingerprints.
#[derive(Debug, Clone)]
pub struct HdcLtcWeightProgramCandidate {
    pub neuron: HdcLtcUnifiedNeuron,
    pub receipt: WeightProgramReceipt,
    pub base_model_digest: String,
    pub candidate_model_digest: String,
}

/// Errors produced while adapting a WeightProgram to a native HDC-LTC neuron.
#[derive(Debug, Error)]
pub enum HdcLtcWeightProgramAdapterError {
    #[error(transparent)]
    Program(#[from] WeightProgramError),
    #[error(transparent)]
    NativeEdit(#[from] HdcLtcParameterEditError),
    #[error("HDC-LTC fingerprint serialization failed: {0}")]
    Fingerprint(String),
    #[error("WeightProgram contains a target that is not an HDC-LTC parameter group")]
    NonHdcTarget,
}

/// Build an architecture- and parameter-digest-bound snapshot for one neuron.
///
/// The target specification digest belongs to the task/probe contract, not the
/// neuron architecture; the caller supplies it and WeightProgram validation
/// requires an exact match.
pub fn hdc_ltc_weight_model_snapshot(
    neuron: &HdcLtcUnifiedNeuron,
    target_specification_digest: impl Into<String>,
) -> Result<WeightModelSnapshot, HdcLtcWeightProgramAdapterError> {
    let config_bytes = serde_json::to_vec(neuron.config())
        .map_err(|error| HdcLtcWeightProgramAdapterError::Fingerprint(error.to_string()))?;
    let architecture_digest = domain_hash(b"symthaea-hdc-ltc-architecture-v1\0", &config_bytes);

    let manifest = HDC_GROUPS
        .iter()
        .map(|(id, name)| HdcLtcManifestEntry {
            id: *id,
            name,
            dimension: neuron.config().dimension,
        })
        .collect::<Vec<_>>();
    let manifest_bytes = serde_json::to_vec(&manifest)
        .map_err(|error| HdcLtcWeightProgramAdapterError::Fingerprint(error.to_string()))?;
    let manifest_digest = domain_hash(b"symthaea-hdc-ltc-manifest-v1\0", &manifest_bytes);

    let mut parameter_hasher = blake3::Hasher::new();
    parameter_hasher.update(b"symthaea-hdc-ltc-parameters-v1\0");
    let mut groups = Vec::with_capacity(HDC_GROUPS.len());
    for (id, _name) in HDC_GROUPS {
        let values = neuron.parameter_group(id).values.as_slice();
        for value in values {
            parameter_hasher.update(&value.to_le_bytes());
        }
        groups.push(ParameterGroupSnapshot {
            target: WeightProgramTarget::HdcLtc(id),
            role: ParameterGroupRole::Hypervector,
            shape: vec![neuron.config().dimension],
            values: values.to_vec(),
            constraints: ParameterGroupConstraints {
                max_l2_norm: Some(2.0),
                ..Default::default()
            },
        });
    }
    let parameter_digest = parameter_hasher.finalize().to_hex().to_string();

    let mut model_hasher = blake3::Hasher::new();
    model_hasher.update(b"symthaea-hdc-ltc-model-v1\0");
    model_hasher.update(architecture_digest.as_bytes());
    model_hasher.update(manifest_digest.as_bytes());
    model_hasher.update(parameter_digest.as_bytes());
    let model_digest = model_hasher.finalize().to_hex().to_string();

    Ok(WeightModelSnapshot {
        format_version: 1,
        architecture_digest,
        manifest_digest,
        model_digest,
        target_specification_digest: target_specification_digest.into(),
        groups,
    })
}

/// Validate a WeightProgram and materialize its parameter changes on a clone.
///
/// Each replacement uses the neuron-native typed edit API, which independently
/// checks dimension, finiteness and the 2.0 L2-norm ceiling. After all edits,
/// state and momentum are reset on the candidate only.
pub fn materialize_hdc_ltc_weight_program(
    neuron: &HdcLtcUnifiedNeuron,
    target_specification_digest: impl Into<String>,
    program: &WeightProgram,
) -> Result<HdcLtcWeightProgramCandidate, HdcLtcWeightProgramAdapterError> {
    let target_specification_digest = target_specification_digest.into();
    let snapshot = hdc_ltc_weight_model_snapshot(neuron, target_specification_digest.clone())?;
    let candidate = program.validate_and_materialize(&snapshot)?;

    let mut candidate_neuron = neuron.clone();
    if snapshot.groups.len() != candidate.groups.len() {
        return Err(HdcLtcWeightProgramAdapterError::NonHdcTarget);
    }

    for (before, after) in snapshot.groups.iter().zip(candidate.groups.iter()) {
        if before.target != after.target || before.shape != after.shape {
            return Err(HdcLtcWeightProgramAdapterError::NonHdcTarget);
        }
        if before.values == after.values {
            continue;
        }
        let WeightProgramTarget::HdcLtc(id) = &after.target else {
            return Err(HdcLtcWeightProgramAdapterError::NonHdcTarget);
        };
        candidate_neuron.try_replace_parameter_group(*id, &after.values)?;
    }

    candidate_neuron.reset_after_parameter_edit();

    let candidate_snapshot =
        hdc_ltc_weight_model_snapshot(&candidate_neuron, target_specification_digest)?;
    Ok(HdcLtcWeightProgramCandidate {
        neuron: candidate_neuron,
        receipt: candidate.receipt,
        base_model_digest: snapshot.model_digest,
        candidate_model_digest: candidate_snapshot.model_digest,
    })
}

fn domain_hash(domain: &[u8], payload: &[u8]) -> String {
    let mut hasher = blake3::Hasher::new();
    hasher.update(domain);
    hasher.update(&(payload.len() as u64).to_le_bytes());
    hasher.update(payload);
    hasher.finalize().to_hex().to_string()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::hdc::hdc_ltc_unified::HdcLtcParameterGroupId;
    use crate::hdc::hdc_ltc_unified::UnifiedConfig;
    use crate::hdc::unified_hv::ContinuousHV;
    use crate::weight_space_program::WeightProgramOperation;

    fn digest(byte: char) -> String {
        std::iter::repeat_n(byte, 64).collect()
    }

    fn neuron() -> HdcLtcUnifiedNeuron {
        HdcLtcUnifiedNeuron::new(
            UnifiedConfig {
                dimension: 64,
                ..Default::default()
            },
            42,
        )
    }

    #[test]
    fn hdc_ltc_candidate_is_detached_and_resets_ephemeral_state() {
        let mut source = neuron();
        source.set_state(ContinuousHV::from_values(vec![0.1; 64]));
        source.evolve_closed_form(0.05, &ContinuousHV::from_values(vec![-0.2; 64]));
        let source_stats_before = source.stats();
        let task_digest = digest('d');
        let snapshot =
            hdc_ltc_weight_model_snapshot(&source, task_digest.clone()).expect("snapshot");
        let target = WeightProgramTarget::HdcLtc(HdcLtcParameterGroupId::GateBias);
        let group = snapshot
            .groups
            .iter()
            .find(|group| group.target == target)
            .expect("gate-bias group");
        let original_values = group.values.clone();
        let program = WeightProgram {
            format_version: 1,
            architecture_digest: snapshot.architecture_digest.clone(),
            manifest_digest: snapshot.manifest_digest.clone(),
            base_model_digest: snapshot.model_digest.clone(),
            target_specification_digest: task_digest.clone(),
            fault_hypothesis_ids: vec!["fault:gate-bias-scale".into()],
            evidence_receipt_ids: vec!["receipt:gate-profile-01".into()],
            max_changed_parameters: 64,
            max_total_l2_delta: 1.0,
            max_abs_delta: 1.0,
            operations: vec![WeightProgramOperation::ScaleRange {
                target,
                start: 0,
                end: 64,
                factor: 1.1,
            }],
        };

        let candidate = materialize_hdc_ltc_weight_program(&source, task_digest, &program)
            .expect("isolated candidate");
        assert_eq!(
            hdc_ltc_weight_model_snapshot(&source, digest('d'))
                .expect("source after edit")
                .model_digest,
            snapshot.model_digest
        );
        assert_ne!(
            candidate.candidate_model_digest,
            candidate.base_model_digest
        );
        assert_eq!(source.stats().state_norm, source_stats_before.state_norm);
        assert_eq!(
            source.stats().running_mean,
            source_stats_before.running_mean
        );
        assert_eq!(candidate.neuron.stats().state_norm, 0.0);
        assert_eq!(candidate.neuron.stats().running_mean, 0.0);
        assert_eq!(candidate.neuron.stats().running_std, 1.0);
        assert_eq!(candidate.neuron.stats().total_time, 0.0);
        assert_eq!(candidate.neuron.stats().update_count, 0);
        let edited = candidate
            .neuron
            .parameter_group(HdcLtcParameterGroupId::GateBias);
        assert!(
            edited
                .values
                .iter()
                .zip(original_values.iter())
                .any(|(a, b)| a != b)
        );
    }

    #[test]
    fn invalid_hdc_norm_is_rejected_before_candidate_materialization() {
        let source = neuron();
        let task_digest = digest('d');
        let snapshot =
            hdc_ltc_weight_model_snapshot(&source, task_digest.clone()).expect("snapshot");
        let program = WeightProgram {
            format_version: 1,
            architecture_digest: snapshot.architecture_digest.clone(),
            manifest_digest: snapshot.manifest_digest.clone(),
            base_model_digest: snapshot.model_digest.clone(),
            target_specification_digest: task_digest,
            fault_hypothesis_ids: vec!["fault:unbounded-role".into()],
            evidence_receipt_ids: vec!["receipt:corrupt-vector-01".into()],
            max_changed_parameters: 64,
            max_total_l2_delta: 100.0,
            max_abs_delta: 100.0,
            operations: vec![WeightProgramOperation::ReplaceGroup {
                target: WeightProgramTarget::HdcLtc(HdcLtcParameterGroupId::GateBias),
                values: vec![1.0; 64],
            }],
        };
        assert!(matches!(
            materialize_hdc_ltc_weight_program(&source, digest('d'), &program),
            Err(HdcLtcWeightProgramAdapterError::Program(
                WeightProgramError::CandidateConstraintViolation
            ))
        ));
    }

    #[test]
    fn stale_task_digest_is_rejected() {
        let source = neuron();
        let snapshot = hdc_ltc_weight_model_snapshot(&source, digest('d')).expect("snapshot");
        let program = WeightProgram {
            format_version: 1,
            architecture_digest: snapshot.architecture_digest.clone(),
            manifest_digest: snapshot.manifest_digest.clone(),
            base_model_digest: snapshot.model_digest.clone(),
            target_specification_digest: digest('e'),
            fault_hypothesis_ids: vec!["fault:tau".into()],
            evidence_receipt_ids: vec!["receipt:one".into()],
            max_changed_parameters: 64,
            max_total_l2_delta: 1.0,
            max_abs_delta: 1.0,
            operations: vec![WeightProgramOperation::ScaleRange {
                target: WeightProgramTarget::HdcLtc(HdcLtcParameterGroupId::TauModulator),
                start: 0,
                end: 64,
                factor: 1.1,
            }],
        };
        assert!(matches!(
            materialize_hdc_ltc_weight_program(&source, digest('d'), &program),
            Err(HdcLtcWeightProgramAdapterError::Program(
                WeightProgramError::StaleDigest("target specification")
            ))
        ));
    }
}
